TLM.f("Tempora/Epi1-1",{"officium":"Feria II infra Hebdomadam I post Epiphaniam","rule":["vide Epi1-0a","Suffragium=Maria2;Papa,Ecclesiæ;;"],"ruleInherited":["ex Sancti/01-06","Gloria","Credo","Prefatio=Epi","Gloria","Credo","Prefatio=Epi"],"fallback":"Tempora/Epi1-0a","from":{"Introitus":"Tempora/Epi1-0a","Oratio":"Tempora/Epi1-0a","Lectio":"Tempora/Epi1-0a","Graduale":"Tempora/Epi1-0a","Evangelium":"Tempora/Epi1-0a","Offertorium":"Tempora/Epi1-0a","Secreta":"Tempora/Epi1-0a","Communio":"Tempora/Epi1-0a","Postcommunio":"Tempora/Epi1-0a","Commemoratio Oratio":"Tempora/Epi1-0a","Commemoratio Secreta":"Tempora/Epi1-0a","Commemoratio Postcommunio":"Tempora/Epi1-0a"},"sections":{"Introitus":[{"k":"text","la":"In excélso throno vidi sedére virum, quem adórat multitúdo Angelórum, psalléntes in unum: ecce, cujus impérii nomen est in ætérnum"},{"k":"ref","la":"Ps 99:1"},{"k":"text","la":"Jubiláte Deo, omnis terra: servíte Dómino in lætítia."},{"k":"macro","name":"Gloria"},{"k":"text","la":"In excélso throno vidi sedére virum, quem adórat multitúdo Angelórum, psalléntes in unum: ecce, cujus impérii nomen est in ætérnum"}],"Oratio":[{"k":"text","la":"Vota, quǽsumus, Dómine, supplicántis pópuli cœlésti pietáte proséquere: ut et, quæ agénda sunt, vídeant, et ad implénda, quæ víderint, convaléscant."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Romános."},{"k":"ref","la":"Rom 12:1-5"},{"k":"text","la":"Fratres: Obsecro vos per misericórdiam Dei, ut exhibeátis córpora vestra hóstiam vivéntem, sanctam, Deo placéntem, rationábile obséquium vestrum. Et nolíte conformári huic sǽculo, sed reformámini in novitáte sensus vestri: ut probétis, quæ sit volúntas Dei bona, et benéplacens, et perfécta. Dico enim per grátiam, quæ data est mihi, ómnibus qui sunt inter vos: Non plus sápere, quam opórtet sápere, sed sápere ad sobrietátem: et unicuique sicut Deus divísit mensúram fídei. Sicut enim in uno córpore multa membra habémus, ómnia autem membra non eúndem actum habent: ita multi unum corpus sumus in Christo, sínguli autem alter alteríus membra: in Christo Jesu, Dómino nostro."}],"Graduale":[{"k":"ref","la":"Ps 71:18 ; 71:3"},{"k":"text","la":"Benedíctus Dóminus, Deus Israël, qui facit mirabília magna solus a sǽculo."},{"k":"text","la":"Suscípiant montes pacem pópulo tuo, et colles justítiam. Allelúja, allelúja","mark":"V"},{"k":"ref","la":"Ps 99:1"},{"k":"text","la":"Jubiláte Deo, omnis terra: servíte Dómino in lætítia. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam."},{"k":"ref","la":"Luc 2:42-52"},{"k":"text","la":"Cum factus esset Jesus annórum duódecim, ascendéntibus illis Jerosólymam secúndum consuetúdinem diéi festi, consummatísque diébus, cum redírent, remánsit puer Jesus in Jerúsalem, et non cognovérunt paréntes ejus. Existimántes autem illum esse in comitátu, venérunt iter diéi, et requirébant eum inter cognátos et notos. Et non inveniéntes, regréssi sunt in Jerúsalem, requiréntes eum. Et factum est, post tríduum invenérunt illum in templo sedéntem in médio doctórum, audiéntem illos et interrogántem eos. Stupébant autem omnes, qui eum audiébant, super prudéntia et respónsis ejus. Et vidéntes admiráti sunt. Et dixit Mater ejus ad illum: Fili, quid fecísti nobis sic? Ecce, pater tuus et ego doléntes quærebámus te. Et ait ad illos: Quid est, quod me quærebátis? Nesciebátis, quia in his, quæ Patris mei sunt, opórtet me esse? Et ipsi non intellexérunt verbum, quod locútus est ad eos. Et descéndit cum eis, et venit Názareth: et erat súbditus illis. Et Mater ejus conservábat ómnia verba hæc in corde suo. Et Jesus proficiébat sapiéntia et ætáte et grátia apud Deum et hómines."}],"Offertorium":[{"k":"ref","la":"Ps 99:1; 99:2"},{"k":"text","la":"Jubiláte Deo, omnis terra, servíte Dómino in lætítia: intráte in conspéctu ejus in exsultatióne: quia Dóminus ipse est Deus."}],"Secreta":[{"k":"text","la":"Oblátum tibi, Dómine, sacrifícium vivíficet nos semper et múniat."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Luc 2:48; 2:49"},{"k":"text","la":"Fili, quid fecísti nobis sic? ego et pater tuus doléntes quærebámus te. Et quid est, quod me quærebátis? nesciebátis, quia in his, quæ Patris mei sunt, opórtet me esse?"}],"Postcommunio":[{"k":"text","la":"Súpplices te rogámus, omnípotens Deus: ut, quos tuis réficis sacraméntis, tibi étiam plácitis móribus dignánter deservíre concédas."},{"k":"macro","name":"Per Dominum"}],"Commemoratio Oratio":[{"k":"rubric","la":"Pro Octavam Epiphaniæ"},{"k":"text","la":"Deus, qui hodiérna die Unigénitum tuum géntibus stella duce revelásti: concéde propítius; ut, qui jam te ex fide cognóvimus, usque ad contemplándam spéciem tuæ celsitúdinis perducámur."},{"k":"macro","name":"Per eumdem"}],"Commemoratio Secreta":[{"k":"rubric","la":"Pro Octavam Epiphaniæ"},{"k":"text","la":"Ecclésiæ tuæ, quǽsumus, Dómine, dona propítius intuere: quibus non jam aurum, thus et myrrha profertur; sed quod eisdem munéribus declarátur, immolátur et súmitur, Jesus Christus, fílius tuus, Dóminus noster:"},{"k":"macro","name":"Qui tecum"}],"Commemoratio Postcommunio":[{"k":"rubric","la":"Pro Octavam Epiphaniæ"},{"k":"text","la":"Præsta, quǽsumus, omnípotens Deus: ut, quæ sollémni celebrámus officio, purificátæ mentis intellegéntia consequámur."},{"k":"macro","name":"Per Dominum"}]},"hr":{"b369ce3f7fe42e11":{"t":"Ps 99, 1\nNa uzvišenom prijestolju vidjeh kako sjedi čovjek. Njemu se klanja mnoštvo anđela koji složno pjevaju: Evo onoga koji vlada vječnim kraljevstvom! (Ps 99, 1) Poklikni Bogu, sva zemljo! Služite Gospodinu veselo.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\nNa uzvišenom prijestolju vidjeh kako sjedi čovjek. Njemu se klanja mnoštvo anđela koji složno pjevaju: Evo onoga koji vlada vječnim kraljevstvom!"},"7099fdc02d57f811":{"t":"<i>Pomolimo se</i>.\nMolimo, Gospodine, prati nebeskom milošću prošnje naroda koji te zaziva, da vidi što treba činiti i da stekne snagu te može vršiti ono što vidi.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"872333974f2a5473":{"t":"Rim 12, 1-5\nČitanje Poslanice bl. Pavla apostola Rimljanima. Braćo: zaklinjem vas milosrđem Božjim da prikažete svoje tijelo kao žrtvu živu, svetu i ugodnu Bogu, da vaše bogoštovlje bude duhovno. Nemojte se izjednačiti s ovim svijetom. Naprotiv, obnovite svoje mišljenje da možete uočiti što je Božja volja, što je dobro, ugodno i savršeno. Po milosti koja mi je dana kažem svakom od vas, da ne cijeni sebe više nego se smije cijeniti, već trijezno prema mjeri vjere koju je Bog kome udijelio. Kao što u jednom tijelu imamo mnogo udova, a svi udovi nemaju istu službu, tako smo mnogi jedno tijelo u Kristu, a svi mi pojedini smo udovi jedan drugome u Kristu Gospodinu našemu."},"ebdb9d170dee2369":{"t":"Ps 71, 18 i 3\nBlagoslovljen Gospodin Bog Izraelov koji jedini čini divna i velika djela od vijeka. Neka planine osjete mir i bregovi pravdu koju daješ narodu svome.\n\nPs 99, 1\n<i>Aleluja</i>, <i>aleluja</i>.\nPoklikni Bogu, sva zemljo! Služite Gospodinu veselo! <i>Aleluja</i>."},"3f677878a41c5a6d":{"t":"Lk 2, 42-52\nSlijedi sveto Evanđelje po Luki. Kad je Isusu bilo dvanaest godina, njegovi roditelji pođu po blagdanskom običaju u Jeruzalem. Kad su prošli blagdani i oni se vraćali, dječak Isus ostade u Jeruzalemu, a da njegovi roditelji nisu znali. Misleći da je među suputnicima, išli su dan hoda, a onda ga stanu tražiti među rođacima i znancima. Ali, kako ga ne nađu, vrate se u Jeruzalem da ga traže. – Poslije tri dana nađu ga u hramu gdje sjedi među učiteljima, kako ih sluša i postavlja pitanja. Svi koji su ga slušali, divili su se njegovoj mudrosti i odgovorima. Kad ga opaze, vrlo se začude. A majka mu reče: »Sine, zašto si nam to učinio? Tvoj otac i ja žalosni smo te tražili.« On im odgovori: »Zašto ste me tražili? Zar niste znali da ja moram biti u onome što pripada mom Ocu?« A oni nisu shvatili njegovih riječi. – On tada pođe s njima i dođe u Nazaret i bio im je poslušan. Njegova je Majka sve ovo čuvala u svom srcu. A Isus je napredovao u mudrosti, dobi i milosti pred Bogom i ljudima."},"4d01621aada35dae":{"t":"Ps 99, 1-2\nPoklikni Bogu, sva zemljo! Služite Gospodinu veselo! Stupite preda nj veselo kličući, jer je samo Bog Gospodin."},"f321c843e76ed500":{"t":"Neka nas vazda oživljuje i brani, Gospodine, žrtva koju ti prinosimo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"93e8203b4ea3a0a5":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi. Gospodine, sveti Oče, svemogući vječni Bože: – jer kad se tvoj Jedinorođenac pojavio u našem smrtnom tijelu, on nas je novim svjetlom svoje besmrtnosti obnovio. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:"},"6741fc27d78054a2":{"t":"Lk 2, 48-49\nSine, zašto si nam to učinio? Tvoj otac i ja žalosni smo te tražili. Zašto ste me tražili? Zar niste znali da ja moram biti u onome što pripada mom Ocu."},"46abd48177cf9e44":{"t":"<i>Pomolimo se</i>.\nPonizno te molimo, svemogući Bože, udijeli da ti služe i ugode dostojnijim vladanjem oni koje krijepiš svojim otajstvima.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
